import sys
import time

class MarriageFunction:
    total_duration = 0.0

    @classmethod
    def do_task(cls, task):
        name = task[0]
        duration = task[1]

        start = time.time()
        time.sleep(duration)
        end = time.time()

        elapsed = end - start
        cls.total_duration += elapsed

        print(f"{name} took {round(elapsed, 2)} seconds")

if __name__ == "__main__":
    tasks = eval(sys.stdin.read().strip())
    for task in tasks:
        MarriageFunction.do_task(task)
